"""The small authored task catalog. Public metadata never includes scripted solutions."""
from dataclasses import dataclass
from pathlib import Path


CHECK_COMMAND = ("python", "-I", "-B", "-m", "unittest", "discover", "-s", "tests", "-t", ".", "-v")
FIXTURES = Path(__file__).resolve().parent / "fixtures"


@dataclass(frozen=True, slots=True)
class TaskSpec:
    id: str
    title: str
    description: str
    source_dir: Path
    editable_files: tuple[str, ...]
    check_command: tuple[str, ...]
    demo_path: str
    demo_content: str
    tags: tuple[str, ...]
    private: bool = False
    project_id: str = ""
    snapshot_id: str = ""
    check_profile: str = "unittest"
    test_paths: tuple[str, ...] = ()
    source_hash: str = ""


_QUANTITY_SOLUTION = '"""Shopping quantities use a fixed unit per ingredient (for example grams)."""
import math


def _validate(values):
    for name, quantity in values.items():
        if not isinstance(name, str) or not name.strip():
            raise ValueError("ingredient names must be non-empty strings")
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)):
            raise ValueError("quantity must be numeric")
        if not math.isfinite(quantity) or quantity < 0:
            raise ValueError("quantity must be finite and non-negative")


def shopping_shortfall(required, stock):
    """Return strictly positive quantities still required for a meal plan."""
    _validate(required)
    _validate(stock)
    result = {}
    for ingredient, amount in required.items():
        missing = max(0, amount - stock.get(ingredient, 0))
        if missing > 0:
            result[ingredient] = missing
    return result
'
_BATCH_SOLUTION = '"""Keep fixed-unit ingredient quantities with their own batch expiry dates."""
from datetime import date


def _quantity(value):
    if type(value) is not int or value <= 0:
        raise ValueError("quantity must be a positive integer")


def add_batch(batches, name, quantity, expires_on):
    """Return new inventory without changing the caller's batch records."""
    if not isinstance(name, str) or not name.strip():
        raise ValueError("name is required")
    name = name.strip().casefold()
    _quantity(quantity)
    date.fromisoformat(expires_on)
    result = [dict(batch) for batch in batches]
    for batch in result:
        if batch["name"].strip().casefold() == name and batch["expires_on"] == expires_on:
            batch["quantity"] += quantity
            batch["expires_on"] = expires_on
            return result
    result.append({"name": name, "quantity": quantity, "expires_on": expires_on})
    return result
'
_LABEL_SOLUTION = '"""Update a sample label and append its audit history."""
import sqlite3


def update_label(database_path, sample_id, label, note=""):
    if label not in {"ham", "spam"}:
        raise ValueError("label must be ham or spam")
    connection = sqlite3.connect(database_path)
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute("SELECT label FROM samples WHERE id = ?", (sample_id,)).fetchone()
        if row is None:
            raise LookupError("sample not found")
        old_label = row[0]
        if old_label == label:
            return {"changed": False, "label": label}
        connection.execute("UPDATE samples SET label = ? WHERE id = ?", (label, sample_id))
        connection.execute(
            "INSERT INTO history(sample_id, old_label, new_label, note) VALUES (?, ?, ?, ?)",
            (sample_id, old_label, label, note),
        )
        connection.commit()
        return {"changed": True, "label": label}
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()
'

_TASKS = (
    TaskSpec("quantity-shortfall", "库存数量缺口", "购物清单把已有食材误当成数量足够。修复固定单位下的缺口计算，保留输入校验与原输入。", FIXTURES / "quantity-shortfall", ("src/quantities.py",), CHECK_COMMAND, "src/quantities.py", _QUANTITY_SOLUTION, ("business-logic", "quantity", "regression")),
    TaskSpec("batch-expiry", "补货批次到期", "新增补货错误地延长旧批次的到期日。保留不同到期日期的独立批次，仅合并相同食材且相同到期日的数量。", FIXTURES / "batch-expiry", ("src/batches.py",), CHECK_COMMAND, "src/batches.py", _BATCH_SOLUTION, ("state", "batch", "expiry")),
    TaskSpec("label-transaction", "标签与历史原子性", "标签已提交而历史写入失败，导致数据与审计记录不一致。修复事务边界，同时保留相同标签无改动和未知样本错误。", FIXTURES / "label-transaction", ("src/labels.py",), CHECK_COMMAND, "src/labels.py", _LABEL_SOLUTION, ("sqlite", "transaction", "rollback")),
)


def get_task(task_id: str) -> TaskSpec:
    for task in _TASKS:
        if task.id == task_id:
            return task
    raise KeyError(task_id)


def list_tasks() -> list[dict]:
    from .workspace import tree_hash
    return [{"id": task.id, "title": task.title, "description": task.description,
             "editable_files": list(task.editable_files), "check_id": "tests",
             "tags": list(task.tags), "source_hash": tree_hash(task.source_dir)}
            for task in _TASKS]

patchtrail/web_imports.py.text:
"""Private, bounded browser-source previews. Importing never runs code or a model."""
from contextlib import contextmanager
from datetime import datetime, timezone
import fcntl
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import tempfile
import threading
import time

from .projects import (MANIFEST_LIMIT, ProjectCatalog, normalize_manifest, preview_project,
                       _publish_directory, _snapshot_file_inventory)
from .workspace import (MAX_FILES, MAX_FILE_BYTES, MAX_TREE_BYTES, WorkspaceError,
                        _canonical, _root, _sha, tree_hash)

IMPORT_BODY_LIMIT = 4 * 1024 * 1024
PREVIEW_ID = re.compile(r"upload-[a-f0-9]{64}\Z")
PREVIEW_TTL = 24 * 60 * 60
MAX_PREVIEWS = 32
MAX_PREVIEW_BYTES = 68 * 1024 * 1024  # 64 MiB source plus bounded manifests/inventories.
METADATA_LIMIT = 512 * 1024
_FIELDS = {"schema_version", "preview_id", "manifest", "files", "source_hash", "created_at", "expires_at"}


class WebImportError(ValueError):
    def __init__(self, code, message, status=400):
        super().__init__(message)
        self.code, self.status = code, status


def _utc(timestamp):
    return datetime.fromtimestamp(timestamp, timezone.utc).isoformat()


def _identity(record):
    return {key: record[key] for key in ("schema_version", "manifest", "files", "source_hash")}


class WebImportStore:
    def __init__(self, directory, catalog: ProjectCatalog, *, clock=time.time):
        self.directory = Path(directory)
        self.catalog, self.clock = catalog, clock
        self.thread_lock = threading.RLock()

    @contextmanager
    def _locked(self):
        with self.thread_lock:
            if self.directory.is_symlink():
                raise WebImportError("import_conflict", "Import preview storage is unavailable", 409)
            self.directory.mkdir(mode=0o700, parents=True, exist_ok=True)
            self.directory.chmod(0o700)
            base = _root(self.directory)
            fd = os.open(base / ".web-import.lock", os.O_CREAT | os.O_RDWR | getattr(os, "O_NOFOLLOW", 0), 0o600)
            try:
                if not stat.S_ISREG(os.fstat(fd).st_mode):
                    raise WebImportError("import_conflict", "Import preview storage is unavailable", 409)
                deadline = time.monotonic() + 5
                while True:
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        break
                    except BlockingIOError:
                        if time.monotonic() >= deadline:
                            raise WebImportError("import_capacity", "Another import is publishing; retry the same preview", 429)
                        time.sleep(.01)
                yield base
            finally:
                fcntl.flock(fd, fcntl.LOCK_UN)
                os.close(fd)

    @staticmethod
    def _validated_input(manifest, files):
        try:
            manifest = normalize_manifest(manifest)
            if len(_canonical(manifest)) > MANIFEST_LIMIT:
                raise WorkspaceError("Project manifest exceeds its size limit")
            if not isinstance(files, list) or not 2 <= len(files) <= MAX_FILES:
                raise WorkspaceError("Select between two and 200 source/test files")
            payload, total = {}, 0
            for item in files:
                if not isinstance(item, dict) or set(item) != {"path", "content"}:
                    raise WorkspaceError("Each source file requires only path and content")
                path, content = item["path"], item["content"]
                if not isinstance(path, str) or path in payload or not isinstance(content, str):
                    raise WorkspaceError("Source paths must be unique and file content must be text")
                if path not in manifest["files"]:
                    raise WorkspaceError("Uploaded source files must exactly match the reviewed manifest")
                if len(PurePosixPath(path).parts) > 17:
                    raise WorkspaceError("Source directory nesting is too deep")
                data = content.encode("utf-8")
                if len(data) > MAX_FILE_BYTES:
                    raise WorkspaceError("Source files must be at most 128 KiB")
                if b"\0" in data:
                    raise WorkspaceError("Binary source files cannot be imported")
                total += len(data)
                if total > MAX_TREE_BYTES:
                    raise WorkspaceError("Source snapshot exceeds 2 MiB")
                payload[path] = data
            if set(payload) != set(manifest["files"]):
                raise WorkspaceError("Uploaded source files must exactly match the reviewed manifest")
            if len({path.casefold() for path in payload}) != len(payload):
                raise WorkspaceError("Source paths must not collide when case is ignored")
            for path in payload:
                if any(parent.as_posix() in payload for parent in PurePosixPath(path).parents):
                    raise WorkspaceError("A source file cannot also be a parent directory")
            return manifest, payload
        except (WorkspaceError, UnicodeError, TypeError, ValueError):
            # Never reflect submitted contents or local filesystem details in a failure.
            raise WebImportError("import_invalid", "Source files, paths, sizes or test manifest do not match the import contract") from None

    def _metadata(self, path):
        try:
            if path.is_symlink() or not path.is_dir() or not PREVIEW_ID.fullmatch(path.name):
                raise ValueError()
            target = path / "metadata.json"
            if target.is_symlink() or not target.is_file() or target.stat().st_size > METADATA_LIMIT:
                raise ValueError()
            record = json.loads(target.read_text(encoding="utf-8"))
            if not isinstance(record, dict) or set(record) != _FIELDS:
                raise ValueError()
            manifest = normalize_manifest(record["manifest"])
            if manifest != record["manifest"] or len(_canonical(manifest)) > MANIFEST_LIMIT:
                raise ValueError()
            if type(record["schema_version"]) is not int or record["schema_version"] != 1:
                raise ValueError()
            if (type(record["created_at"]) is not int or type(record["expires_at"]) is not int
                    or record["created_at"] < 0 or record["expires_at"] - record["created_at"] != PREVIEW_TTL):
                raise ValueError()
            rows = record["files"]
            if not isinstance(rows, list) or not 2 <= len(rows) <= MAX_FILES:
                raise ValueError()
            for row in rows:
                if (not isinstance(row, dict) or set(row) != {"path", "bytes", "sha256"}
                        or type(row["bytes"]) is not int or not 0 <= row["bytes"] <= MAX_FILE_BYTES
                        or not isinstance(row["sha256"], str) or not re.fullmatch(r"[a-f0-9]{64}", row["sha256"])):
                    raise ValueError()
            if ([row["path"] for row in rows] != manifest["files"]
                    or sum(row["bytes"] for row in rows) > MAX_TREE_BYTES
                    or not isinstance(record["source_hash"], str)
                    or not re.fullmatch(r"[a-f0-9]{64}", record["source_hash"])):
                raise ValueError()
            expected = "upload-" + _sha(_canonical(_identity(record)))
            if record["preview_id"] != expected or path.name != expected:
                raise ValueError()
            return record
        except (OSError, ValueError, TypeError, KeyError, WorkspaceError):
            raise WebImportError("import_conflict", "Import preview metadata no longer matches; preview the files again", 409) from None

    def _load(self, base, preview_id, now):
        if not isinstance(preview_id, str) or not PREVIEW_ID.fullmatch(preview_id):
            raise WebImportError("import_invalid", "Invalid import preview identity")
        path = base / preview_id
        if not path.exists() and not path.is_symlink():
            raise WebImportError("import_not_found", "Import preview was not found; preview the files again", 404)
        record = self._metadata(path)
        if now >= record["expires_at"]:
            shutil.rmtree(path)
            raise WebImportError("import_expired", "Import preview expired; preview the files again", 410)
        try:
            source = _root(path / "source")
            _snapshot_file_inventory(source, record["manifest"])
            actual = preview_project(source, record["manifest"])
            if actual["files"] != record["files"] or tree_hash(source) != record["source_hash"]:
                raise ValueError()
        except (OSError, ValueError, WorkspaceError):
            raise WebImportError("import_conflict", "Import preview source changed; preview the files again", 409) from None
        return record, source

    def _prune(self, base, now, skip=None):
        records = []
        for path in sorted(base.iterdir()):
            if path.name == ".web-import.lock":
                continue
            if path.name.startswith(".preview-") and path.is_dir() and not path.is_symlink():
                # All producers hold this same lock. A leftover staging directory is abandoned.
                shutil.rmtree(path)
                continue
            if path.name == skip:
                continue
            record = self._metadata(path)
            if now >= record["expires_at"]:
                shutil.rmtree(path)
            else:
                records.append(record)
        return records

    def _committed_task(self, record):
        identity = {"manifest": record["manifest"], "source_hash": record["source_hash"]}
        snapshot = _sha(_canonical(identity))
        destination = self.catalog.directory / snapshot
        if not destination.exists() and not destination.is_symlink():
            return None
        return self.catalog._metadata(self.catalog._load(destination))

    def _response(self, record, *, created=False):
        response = {"preview_id": record["preview_id"], "manifest": record["manifest"],
                    "files": record["files"], "file_count": len(record["files"]),
                    "total_bytes": sum(row["bytes"] for row in record["files"]),
                    "created_at": _utc(record["created_at"]), "expires_at": _utc(record["expires_at"]),
                    "created": created, "execution_performed": False, "model_called": False}
        task = self._committed_task(record)
        if task is not None:
            response["committed_task"] = task
        return response

    def preview(self, manifest, files):
        manifest, payload = self._validated_input(manifest, files)
        with self._locked() as base:
            now = int(self.clock())
            existing = self._prune(base, now)
            staging = Path(tempfile.mkdtemp(prefix=".preview-", dir=base))
            try:
                source = staging / "source"
                source.mkdir(mode=0o755)
                for relative, content in payload.items():
                    target = source / relative
                    target.parent.mkdir(parents=True, exist_ok=True)
                    with target.open("xb") as stream:
                        stream.write(content)
                        stream.flush()
                        os.fsync(stream.fileno())
                    target.chmod(0o444)
                checked = preview_project(source, manifest)
                identity = {"schema_version": 1, "manifest": manifest, "files": checked["files"],
                            "source_hash": tree_hash(source)}
                preview_id = "upload-" + _sha(_canonical(identity))
                destination = base / preview_id
                if destination.exists() or destination.is_symlink():
                    record, _ = self._load(base, preview_id, now)
                    if _identity(record) != identity:
                        raise WebImportError("import_conflict", "Import preview identity collision", 409)
                    return self._response(record)
                footprint = sum(row["bytes"] for row in checked["files"]) + len(_canonical(identity))
                used = sum(sum(row["bytes"] for row in record["files"]) + len(_canonical(_identity(record))) for record in existing)
                if len(existing) >= MAX_PREVIEWS or used + footprint > MAX_PREVIEW_BYTES:
                    raise WebImportError("import_capacity", "Import preview storage is full; expired previews are cleared after 24 hours", 429)
                record = {**identity, "preview_id": preview_id, "created_at": now, "expires_at": now + PREVIEW_TTL}
                with (staging / "metadata.json").open("xb") as stream:
                    stream.write(_canonical(record) + b"\n")
                    stream.flush()
                    os.fsync(stream.fileno())
                (staging / "metadata.json").chmod(0o400)
                _publish_directory(staging, destination)
                return self._response(record, created=True)
            except WebImportError:
                raise
            except (OSError, ValueError, TypeError, WorkspaceError):
                raise WebImportError("import_invalid", "Import files could not be staged under the bounded source contract") from None
            finally:
                if staging.exists():
                    shutil.rmtree(staging)

    def get(self, preview_id):
        with self._locked() as base:
            now = int(self.clock())
            record, _ = self._load(base, preview_id, now)
            self._prune(base, now, skip=preview_id)
            return self._response(record)

    def commit(self, preview_id):
        with self._locked() as base:
            now = int(self.clock())
            record, source = self._load(base, preview_id, now)
            self._prune(base, now, skip=preview_id)
            try:
                task = self.catalog.import_project(source, record["manifest"], expected_inventory=record["files"])
            except (OSError, ValueError, WorkspaceError):
                raise WebImportError("import_conflict", "The reviewed import could not be committed; inspect this preview before retrying", 409) from None
            created = task.pop("created")
            return {"task": task, "created": created, "preview_id": preview_id,
                    "execution_performed": False, "model_called": False}

patchtrail/workspace.py.text:
"""Bounded fixture workspaces and exact, approval-bound single-file proposals."""
from contextlib import contextmanager
import difflib
import ctypes
import fcntl
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import sys
import tempfile
import time

from .tasks import TaskSpec


MAX_FILES = 200
MAX_FILE_BYTES = 128 * 1024
MAX_TREE_BYTES = 2 * 1024 * 1024
MAX_PATCH_BYTES = 16 * 1024
MAX_BUNDLE_FILES = 3
MAX_BUNDLE_BYTES = 384 * 1024
MAX_READ_CHARACTERS = 20000
RUN_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,95}\Z")


class WorkspaceError(ValueError):
    """A requested path, fixture or proposal violates the workspace contract."""


def _canonical(value) -> bytes:
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"),
                      allow_nan=False).encode("utf-8")


def _sha(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def _root(directory: Path) -> Path:
    directory = Path(directory)
    if directory.is_symlink():
        raise WorkspaceError("Workspace roots cannot be symlinks")
    try:
        resolved = directory.resolve(strict=True)
    except OSError as exc:
        raise WorkspaceError("Workspace is unavailable") from exc
    if not resolved.is_dir():
        raise WorkspaceError("Workspace must be a directory")
    return resolved


def _files(directory: Path) -> list[Path]:
    root = _root(directory)
    found, pending, total = [], [(root, 0)], 0
    while pending:
        parent, depth = pending.pop()
        if depth > 16:
            raise WorkspaceError("Workspace directory nesting is too deep")
        for child in sorted(parent.iterdir()):
            if child.is_symlink():
                raise WorkspaceError("Symlinks are not allowed in workspaces")
            if child.name == "__pycache__" or child.suffix == ".pyc":
                continue
            mode = child.stat().st_mode
            if stat.S_ISDIR(mode):
                pending.append((child, depth + 1))
            elif stat.S_ISREG(mode):
                size = child.stat().st_size
                total += size
                if size > MAX_FILE_BYTES or total > MAX_TREE_BYTES:
                    raise WorkspaceError("Workspace exceeds its file or total size limit")
                found.append(child)
                if len(found) > MAX_FILES:
                    raise WorkspaceError("Workspace contains too many files")
            else:
                raise WorkspaceError("Only regular files and directories are allowed")
    return sorted(found, key=lambda path: path.relative_to(root).as_posix())


def _hash_files(root: Path, files: list[Path]) -> str:
    digest = hashlib.sha256()
    for path in files:
        relative = path.relative_to(root).as_posix().encode("utf-8")
        content = path.read_bytes()
        if len(content) > MAX_FILE_BYTES:
            raise WorkspaceError("Workspace file changed beyond its size limit")
        digest.update(len(relative).to_bytes(4, "big"))
        digest.update(relative)
        digest.update(len(content).to_bytes(8, "big"))
        digest.update(content)
    return digest.hexdigest()


def tree_hash(directory: Path) -> str:
    root = _root(directory)
    return _hash_files(root, _files(root))


def _source_hash(task: TaskSpec) -> str:
    value = tree_hash(task.source_dir)
    if task.source_hash and value != task.source_hash:
        raise WorkspaceError("Imported source snapshot changed after registration")
    return value


def _relative(path: str) -> str:
    if not isinstance(path, str) or not path or "\x00" in path or "\\" in path:
        raise WorkspaceError("A normalized relative POSIX path is required")
    parsed = PurePosixPath(path)
    if (parsed.is_absolute() or any(part in {"", ".", ".."} for part in path.split("/"))
            or parsed.as_posix() != path or len(path) > 512):
        raise WorkspaceError("Path must stay inside the workspace")
    return parsed.as_posix()


def _path(workspace: Path, path: str) -> Path:
    root = _root(workspace)
    relative = _relative(path)
    current = root
    for part in PurePosixPath(relative).parts:
        current = current / part
        if current.is_symlink():
            raise WorkspaceError("Symlink paths are not allowed")
    try:
        resolved = current.resolve(strict=True)
    except OSError as exc:
        raise WorkspaceError("Requested file does not exist") from exc
    if not resolved.is_relative_to(root) or not resolved.is_file():
        raise WorkspaceError("Requested path is not a workspace file")
    if resolved.stat().st_size > MAX_FILE_BYTES:
        raise WorkspaceError("Requested file exceeds its size limit")
    return resolved


@contextmanager
def _creation_lock(base: Path, run_id: str):
    lock_path = base / ("." + run_id + ".workspace.lock")
    descriptor = os.open(lock_path, os.O_CREAT | os.O_RDWR | getattr(os, "O_NOFOLLOW", 0), 0o600)
    deadline = time.monotonic() + 5
    try:
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    raise WorkspaceError("Workspace creation is already in progress")
                time.sleep(0.01)
        yield
    finally:
        fcntl.flock(descriptor, fcntl.LOCK_UN)
        os.close(descriptor)


def _verify_existing(target: Path, task: TaskSpec) -> Path:
    _source_hash(task)
    root = _root(target)
    source_root = _root(task.source_dir)
    source_files = {path.relative_to(source_root).as_posix(): path for path in _files(source_root)}
    target_files = {path.relative_to(root).as_posix(): path for path in _files(root)}
    if set(source_files) != set(target_files):
        raise WorkspaceError("Existing workspace does not have the fixture's file inventory")
    for relative, source in source_files.items():
        if relative not in task.editable_files and source.read_bytes() != target_files[relative].read_bytes():
            raise WorkspaceError("Existing workspace has changed immutable fixture files")
    return root


def prepare_workspace(base: Path, run_id: str, task: TaskSpec) -> Path:
    if not isinstance(run_id, str) or not RUN_ID.fullmatch(run_id):
        raise WorkspaceError("Invalid run ID")
    base = Path(base)
    if base.is_symlink():
        raise WorkspaceError("Workspace base cannot be a symlink")
    base.mkdir(parents=True, exist_ok=True)
    base = _root(base)
    source = _root(task.source_dir)
    source_hash = _source_hash(task)
    target = base / run_id
    with _creation_lock(base, run_id):
        if target.exists() or target.is_symlink():
            return _verify_existing(target, task)
        staging = Path(tempfile.mkdtemp(prefix="." + run_id + "-", dir=base))
        try:
            for original in _files(source):
                relative = original.relative_to(source)
                destination = staging / relative
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(original.read_bytes())
                destination.chmod(0o644)
            for directory in (path for path in staging.rglob("*") if path.is_dir()):
                directory.chmod(0o755)
            staging.chmod(0o755)
            if tree_hash(staging) != source_hash or tree_hash(source) != source_hash:
                raise WorkspaceError("Fixture changed while copying")
            if target.exists() or target.is_symlink():
                raise WorkspaceError("Workspace destination appeared while copying")
            staging.rename(target)
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    return target


def read_file(workspace: Path, path: str, start: int = 1, end: int = 200) -> dict:
    if type(start) is not int or type(end) is not int or start < 1 or end < start or end - start >= 400:
        raise WorkspaceError("Read range must contain between 1 and 400 lines")
    target = _path(workspace, path)
    content = target.read_bytes()
    try:
        lines = content.decode("utf-8").splitlines()
    except UnicodeDecodeError as exc:
        raise WorkspaceError("Only UTF-8 text files can be read") from exc
    rendered, count, truncated = [], 0, False
    for number in range(start, min(end, len(lines)) + 1):
        line = f"{number}: {lines[number - 1]}"
        remaining = MAX_READ_CHARACTERS - count
        if remaining <= 0:
            truncated = True
            break
        if len(line) > remaining:
            rendered.append(line[:remaining])
            truncated = True
            break
        rendered.append(line)
        count += len(line) + 1
    return {"path": _relative(path), "text": "\n".join(rendered),
            "content_sha256": _sha(content), "start": start, "end": min(end, len(lines)),
            "truncated": truncated}


def search_code(workspace: Path, query: str) -> dict:
    if not isinstance(query, str) or not query or len(query) > 200 or "\x00" in query:
        raise WorkspaceError("Search query must contain 1 to 200 characters")
    root = _root(workspace)
    hits = []
    for target in _files(root):
        try:
            lines = target.read_text(encoding="utf-8").splitlines()
        except UnicodeDecodeError:
            continue
        for number, line in enumerate(lines, 1):
            if query in line:
                if len(hits) >= 30:
                    return {"query": query, "hits": hits, "truncated": True}
                hits.append({"path": target.relative_to(root).as_posix(), "line": number, "text": line[:500]})
    return {"query": query, "hits": hits, "truncated": False}


def build_proposal(task: TaskSpec, workspace: Path, path: str, content: str) -> dict:
    path = _relative(path)
    if path not in task.editable_files:
        raise WorkspaceError("Only the task's editable source file can be proposed")
    if not isinstance(content, str):
        raise WorkspaceError("Replacement content must be text")
    try:
        replacement = content.encode("utf-8")
    except UnicodeEncodeError as exc:
        raise WorkspaceError("Replacement content must be valid UTF-8") from exc
    limit = MAX_FILE_BYTES if task.private else MAX_PATCH_BYTES
    if len(replacement) > limit:
        raise WorkspaceError("Replacement content exceeds its size limit")
    _verify_existing(workspace, task)
    old = _path(workspace, path).read_bytes()
    if old == replacement:
        raise WorkspaceError("Proposal makes no change")
    try:
        old_text = old.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise WorkspaceError("Editable source must be UTF-8 text") from exc
    diff = _patch_diff(path, old_text, content)
    payload = {"task_id": task.id, "path": path, "content": content,
               "old_sha256": _sha(old), "new_sha256": _sha(replacement),
               "base_workspace_hash": tree_hash(workspace), "source_hash": _source_hash(task),
               "diff": diff}
    return {"digest": _sha(_canonical(payload)), **payload}


def apply_proposal(task: TaskSpec, workspace: Path, proposal: dict) -> None:
    if not isinstance(proposal, dict):
        raise WorkspaceError("Proposal must be an object")
    if "files" in proposal:
        _apply_patch_bundle(task, workspace, proposal)
        return
    fields = {"digest", "task_id", "path", "content", "old_sha256", "new_sha256",
              "base_workspace_hash", "source_hash", "diff"}
    if set(proposal) != fields or proposal["task_id"] != task.id:
        raise WorkspaceError("Proposal identity or fields do not match the task")
    expected = build_proposal(task, workspace, proposal["path"], proposal["content"])
    if proposal != expected:
        raise WorkspaceError("Proposal digest, source or workspace no longer matches approval")
    target = _path(workspace, proposal["path"])
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(prefix=".patchtrail-", suffix=".tmp", dir=target.parent, delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(proposal["content"].encode("utf-8"))
            stream.flush()
            os.fsync(stream.fileno())
        temporary.chmod(0o644)
        root = _root(workspace)
        # Exclude only this exact staging path, never a name pattern a caller could imitate.
        current = _hash_files(root, [path for path in _files(root) if path != temporary])
        if current != proposal["base_workspace_hash"]:
            raise WorkspaceError("Workspace changed before proposal publication")
        os.replace(temporary, target)
        temporary = None
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _patch_diff(path: str, old: str, new: str) -> str:
    """Produce an exportable unified diff, including missing-final-newline markers."""
    parts = []
    for line in difflib.unified_diff(old.splitlines(keepends=True), new.splitlines(keepends=True),
                                     fromfile="a/" + path, tofile="b/" + path):
        if not line.endswith("\n"):
            parts.extend((line + "\n", "\\ No newline at end of file\n"))
        else:
            parts.append(line)
    return "".join(parts)


def build_patch_bundle(task: TaskSpec, workspace: Path, files: list[dict]) -> dict:
    """Bind one to three existing source replacements to one approval digest."""
    if not isinstance(files, list) or not 1 <= len(files) <= MAX_BUNDLE_FILES:
        raise WorkspaceError("A patch bundle requires one to three source files")
    _verify_existing(workspace, task)
    entries, seen, size = [], set(), 0
    for entry in files:
        if not isinstance(entry, dict) or set(entry) != {"path", "content"}:
            raise WorkspaceError("Each replacement requires exactly path and content")
        path = _relative(entry["path"])
        if path not in task.editable_files or path in seen:
            raise WorkspaceError("Replacement path is duplicated or not editable")
        seen.add(path)
        content = entry["content"]
        if not isinstance(content, str):
            raise WorkspaceError("Replacement content must be text")
        try:
            replacement = content.encode("utf-8")
            old = _path(workspace, path).read_bytes()
            old_text = old.decode("utf-8")
        except (UnicodeError, OSError) as exc:
            raise WorkspaceError("Source and replacement must be available UTF-8 text") from exc
        size += len(replacement)
        if len(replacement) > MAX_FILE_BYTES or size > MAX_BUNDLE_BYTES:
            raise WorkspaceError("Patch bundle exceeds its size limit")
        if old == replacement:
            raise WorkspaceError("Every proposed file must make a change")
        entries.append({"path": path, "content": content, "old_sha256": _sha(old),
                        "new_sha256": _sha(replacement), "diff": _patch_diff(path, old_text, content)})
    entries.sort(key=lambda entry: entry["path"])
    payload = {"schema_version": 2, "task_id": task.id, "files": entries,
               "base_workspace_hash": tree_hash(workspace), "source_hash": _source_hash(task),
               "diff": "".join(entry["diff"] for entry in entries)}
    return {"digest": _sha(_canonical(payload)), **payload}


def _exchange_directories(left: Path, right: Path) -> None:
    """Atomically exchange two directories on supported development/server systems.

    Do not fall back to sequential publication: a missing primitive fails before
    the original workspace changes. Linux and macOS support a directory swap.
    """
    library = ctypes.CDLL(None, use_errno=True)
    left_bytes, right_bytes = os.fsencode(left), os.fsencode(right)
    if sys.platform.startswith("linux") and hasattr(library, "renameat2"):
        operation = library.renameat2
        operation.argtypes = (ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint)
        operation.restype = ctypes.c_int
        result = operation(-100, left_bytes, -100, right_bytes, 2)  # RENAME_EXCHANGE
    elif sys.platform == "darwin" and hasattr(library, "renamex_np"):
        operation = library.renamex_np
        operation.argtypes = (ctypes.c_char_p, ctypes.c_char_p, ctypes.c_uint)
        operation.restype = ctypes.c_int
        result = operation(left_bytes, right_bytes, 2)  # RENAME_SWAP
    else:
        raise WorkspaceError("Atomic directory exchange is unavailable on this platform")
    if result != 0:
        error = ctypes.get_errno()
        raise WorkspaceError("Atomic patch publication failed") from OSError(error, os.strerror(error))


def _apply_patch_bundle(task: TaskSpec, workspace: Path, proposal: dict) -> None:
    fields = {"digest", "schema_version", "task_id", "files", "base_workspace_hash", "source_hash", "diff"}
    if (set(proposal) != fields or type(proposal.get("schema_version")) is not int
            or proposal.get("schema_version") != 2 or proposal.get("task_id") != task.id):
        raise WorkspaceError("Patch bundle identity or fields do not match the task")
    entries = proposal.get("files")
    if not isinstance(entries, list) or any(not isinstance(entry, dict) for entry in entries):
        raise WorkspaceError("Patch bundle files are invalid")
    replacements = [{"path": entry.get("path"), "content": entry.get("content")} for entry in entries]
    root = _root(workspace)
    with _creation_lock(root.parent, root.name):
        if proposal != build_patch_bundle(task, root, replacements):
            raise WorkspaceError("Patch bundle digest, source or workspace no longer matches approval")
        staging = Path(tempfile.mkdtemp(prefix=".bundle-", dir=root.parent))
        published = False
        try:
            for original in _files(root):
                target = staging / original.relative_to(root)
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(original.read_bytes())
                target.chmod(0o644)
            if tree_hash(staging) != proposal["base_workspace_hash"]:
                raise WorkspaceError("Workspace changed while copying the patch publication baseline")
            for entry in entries:
                (staging / entry["path"]).write_text(entry["content"], encoding="utf-8", newline="")
            for directory in (path for path in staging.rglob("*") if path.is_dir()):
                directory.chmod(0o755)
            staging.chmod(0o755)
            _verify_existing(staging, task)
            if tree_hash(root) != proposal["base_workspace_hash"] or _source_hash(task) != proposal["source_hash"]:
                raise WorkspaceError("Workspace or source changed before patch publication")
            _exchange_directories(root, staging)
            published = True
        finally:
            # Before exchange staging is unpublished; after exchange it is the
            # former complete workspace. The visible path never contains a half patch.
            try:
                shutil.rmtree(staging)
            except OSError:
                if not published:
                    raise
                # Publication is already complete. Failure to remove the old,
                # private tree must not misreport the approved commit as failed.
